#include <stdio.h>
typedef struct { int threshold; int count; } Context;
static void count_above(int x,void *opaque){Context *c=opaque;if(x>c->threshold)++c->count;}
int main(void) {
    int n; Context context={0,0};
    if(scanf("%d%d", &n, &context.threshold)!=2 || n<0 || n>20) return 1;
    void (*visit)(int,void*)=count_above;
    for(int i=0;i<n;++i){int x;if(scanf("%d",&x)!=1)return 1;visit(x,&context);}
    printf("%d\n",context.count);
    return 0;
}

