#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
typedef struct { int *data; size_t size, capacity; } Vector;
static int reserve(Vector *v, size_t requested) {
    if (requested <= v->capacity) return 1;
    if (requested > SIZE_MAX / sizeof *v->data) return 0;
    int *next = realloc(v->data, requested * sizeof *next);
    if (!next) return 0;
    v->data = next;
    v->capacity = requested;
    return 1;
}
static int push(Vector *v, int value) {
    if (v->size == v->capacity) {
        if (v->capacity > SIZE_MAX / 2) return 0;
        size_t next = v->capacity ? v->capacity * 2 : 1;
        if (!reserve(v, next)) return 0;
    }
    v->data[v->size++] = value;
    return 1;
}
static int pop(Vector *v, int *out) {
    if (!v->size) return 0;
    *out = v->data[--v->size];
    return 1;
}
static int at(const Vector *v, size_t index, int *out) {
    if (index >= v->size) return 0;
    *out = v->data[index];
    return 1;
}
static void clear(Vector *v) { v->size = 0; }
static void destroy(Vector *v) { free(v->data); *v = (Vector){0}; }
int main(void) {
    Vector values = {0}; int q, failed=0;
    if (scanf("%d", &q)!=1 || q<0 || q>200) return 1;
    for (int i=0;i<q;++i) {
        char command; int value; size_t index;
        if (scanf(" %c", &command)!=1) { failed=1; break; }
        if (command=='+') {
            if (scanf("%d",&value)!=1 || !push(&values,value)) { failed=1; break; }
        } else if (command=='-') {
            if (pop(&values,&value)) printf("%d\n",value); else puts("ПУСТО");
        } else if (command=='?') {
            if (scanf("%zu",&index)!=1) { failed=1; break; }
            if (at(&values,index,&value)) printf("%d\n",value); else puts("ОШИБКА");
        } else if (command=='r') {
            if (scanf("%zu",&index)!=1 || !reserve(&values,index)) { failed=1; break; }
        } else if (command=='c') clear(&values);
        else if (command=='s') printf("%zu %zu\n",values.size,values.capacity);
        else { failed=1; break; }
    }
    destroy(&values);
    return failed;
}
